template <typename It, typename Pred>
bool none_of(It first, It last, Pred pred) {
    for (; first != last; ++first) {
        if (pred(*first)) {
            return false;
        }
    }
    return true;
}

// Concept: Uses iterator types and generic predicate (lambda or function object)
// Example Call: none_of(v.begin(), v.end(), [](int x){ return x < 0; });
